const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextInt() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        let res = 0;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            res = res * 10 + (input.charCodeAt(pos) - 48);
            pos++;
        }
        return res;
    }

    const N = nextInt();
    if (N === null) return;
    const M = nextInt();

    const adj = new Int32Array(N);

    for (let i = 0; i < M; i++) {
        const u = nextInt() - 1;
        const v = nextInt() - 1;
        adj[u] |= (1 << v);
        adj[v] |= (1 << u);
    }

    let count = 0;

    function dfs(i, allowedMask) {
        if (i === N) {
            count++;
            return;
        }

        // Opção 1: Não incluir o ingrediente i
        dfs(i + 1, allowedMask);

        // Opção 2: Incluir o ingrediente i (se for compatível com os anteriores)
        if ((allowedMask & (1 << i)) !== 0) {
            dfs(i + 1, allowedMask & ~adj[i]);
        }
    }

    const initialAllowed = (1 << N) - 1;
    dfs(0, initialAllowed);

    // Subtrai o conjunto vazio, pois o sanduíche deve conter ao menos um ingrediente
    console.log(count - 1);
}

main();
